import { c } from 'ttag';

import { CreateTokenData, createToken, getTokenStatus } from '@proton/shared/lib/api/payments';
import { PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';
import { getHostname } from '@proton/shared/lib/helpers/url';
import { Api } from '@proton/shared/lib/interfaces';

import PaymentVerificationModal from './PaymentVerificationModal';
import {
    AmountAndCurrency,
    CardPayment,
    ExistingPayment,
    PaymentTokenResult,
    TokenPaymentMethod,
    WrappedCardPayment,
    isExistingPayment,
    isTokenPaymentMethod,
} from './interface';
import { toTokenPaymentMethod } from './paymentTokenToParams';

const { STATUS_PENDING, STATUS_CHARGEABLE, STATUS_CONSUMED, STATUS_NOT_SUPPORTED } = PAYMENT_TOKEN_STATUS;

const DELAY_LISTENING = 1000;

/**
 * Initialize new tab and listen it
 */
export const process = (
    {
        Token,
        api,
        ApprovalURL,
        ReturnHost,
        signal,
    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
        api: Api;
        signal: AbortSignal;
    },
    delayListening = DELAY_LISTENING
) => {
    const tab = window.open(ApprovalURL);

    return new Promise<void>((resolve, reject) => {
        let settled = false;
        let timer: ReturnType<typeof setTimeout> | undefined;
        let elapsed = 0;

        const cleanup = () => {
            if (timer !== undefined) {
                clearTimeout(timer);
            }
            window.removeEventListener('message', onMessage, false);
            signal.removeEventListener('abort', abort);
            tab?.close();
        };

        const finish = (error?: unknown) => {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            if (error) {
                reject(error);
            } else {
                resolve();
            }
        };

        const poll = async () => {
            if (settled) {
                return;
            }
            if (signal.aborted || tab?.closed) {
                finish();
                return;
            }
            try {
                const { Status } = await api({ ...getTokenStatus(Token), signal });
                if (settled) {
                    return;
                }
                if (Status !== STATUS_PENDING || elapsed >= 150000) {
                    finish();
                    return;
                }
                elapsed += delayListening;
                timer = setTimeout(poll, delayListening);
            } catch (error) {
                finish(error);
            }
        };

        const onMessage = (event: MessageEvent) => {
            if (getHostname(event.origin) !== ReturnHost) {
                return;
            }
            if (event.data?.cancel === '1') {
                finish();
            } else {
                if (timer !== undefined) {
                    clearTimeout(timer);
                }
                void poll();
            }
        };

        const abort = () => finish();
        signal.addEventListener('abort', abort);
        window.addEventListener('message', onMessage, false);
        if (signal.aborted) {
            finish();
        } else {
            timer = setTimeout(poll, delayListening);
        }
    });
};

/**
 * Prepares the parameters and makes the API call to create the payment token.
 *
 * @param params
 * @param api
 * @param amountAndCurrency
 */
const fetchPaymentToken = async (
    {
        params,
        api,
    }: {
        params: WrappedCardPayment | ExistingPayment;
        api: Api;
    },
    amountAndCurrency?: AmountAndCurrency
): Promise<PaymentTokenResult> => {
    const data: CreateTokenData = { ...amountAndCurrency, ...params };

    return api<PaymentTokenResult>({
        ...createToken(data),
        notificationExpiration: 10000,
    });
};

/**
 * Creates a {@link TokenPaymentMethod} from the credit card details or from the existing (saved) payment method.
            api,
            params,
        }: { mode?: 'add-card'; api: Api; params: WrappedCardPayment | TokenPaymentMethod | ExistingPayment },
        amountAndCurrency?: AmountAndCurrency
    ): Promise<TokenPaymentMethod> =>
        createPaymentToken({ mode, api, params, verify }, amountAndCurrency);

export const getDefaultVerifyPayment = (createModal: (modal: JSX.Element) => void, api: Api): VerifyPayment => {
    const verify: VerifyPayment = async ({ mode, Payment, Token, ApprovalURL, ReturnHost }) =>
        new Promise<TokenPaymentMethod>((resolve, reject) => {
            createModal(
                <PaymentVerificationModal
                    mode={mode}
                    payment={Payment}
                    token={Token}
                    onSubmit={resolve}
                    onClose={reject}
                    onProcess={() => {
                        const abort = new AbortController();
                        return {
                            promise: process({ Token, api, ApprovalURL, ReturnHost, signal: abort.signal }),
                            abort,
                        };
                    }}
                />
            );
        });
    return verify;
};
